sys_script_include.script:
var EnvironmentalComplianceKPI = Class.create();
EnvironmentalComplianceKPI.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getTotalComplaints: function() {
        var gr = new GlideRecord('x_snc_environment_0_complaint');
        gr.query();
        return gr.getRowCount();
    },

    getHighRiskComplaints: function() {
        var gr = new GlideRecord('x_snc_environment_0_complaint');

        // Change 'risk_level' if your actual field name is different
        gr.addQuery('risk_level', 'High');
        gr.query();

        return gr.getRowCount();
    },

    getResolvedCases: function() {
        var gr = new GlideRecord('x_snc_environment_0_complaint');

        // Change 'status' values if your actual choices are different
        gr.addQuery('status', 'Resolved');
        gr.query();

        return gr.getRowCount();
    },

    type: 'EnvironmentalComplianceKPI'
});
